// ISC 12 Mathematics ch16 Linear Programming — practice bank with independent re-solve checks. Every corner is
// recomputed by intersecting boundary lines and keeping the feasible intersections (lp.mjs); every optimum by
// evaluating Z at the corners AND by a brute-force grid search of the region; every unbounded case by the open
// half-plane test on a large grid; every formulation by comparing the stated inequality with the word problem at
// sample points. All regions, products and contexts are SOYL's own (D-036); the CBSE 12 ch12 bank was checked so
// that no region, objective or wording is reused. ISC scope: at most two variables and three non-trivial constraints.
import { Q, mk } from '../../isc-12-mathematics-ch01/src/lib.mjs';
import { solveLP, corners, feasible, sameSet } from './lp.mjs';

/** String.raw, except that a backslash-n not followed by a lower-case letter becomes a newline. */
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n(?![a-z])/g, '\n');

/** Regions used by the bank and the decks (x ≥ 0, y ≥ 0 always added). */
export const REG = {
  A1: [[1, 1, '<=', 9], [1, 3, '<=', 15]], // corners (0,0) (9,0) (6,3) (0,5)
  A2: [[2, 1, '<=', 14], [1, 2, '<=', 13]], // dairy: (0,0) (7,0) (5,4) (0,6.5)
  A3: [[1, 1, '<=', 12], [2, 1, '<=', 20], [1, 3, '<=', 30]], // handloom: (0,0) (10,0) (8,4) (3,9) (0,10)
  U1: [[1, 1, '>=', 8], [1, 3, '>=', 12]], // unbounded: (0,8) (6,2) (12,0)
  U2: [[2, 1, '>=', 10], [1, 1, '>=', 7], [1, 2, '>=', 10]], // canteen diet: (0,10) (3,4) (4,3) (10,0)
  M1: [[1, 2, '>=', 6], [1, 1, '<=', 8], [1, 0, '<=', 6]], // mixed, bounded: (6,0) (6,2) (0,8) (0,3)
  E1: [[1, 1, '<=', 4], [3, 2, '>=', 18]], // empty
  T: [[1, 0, '<=', 50], [0, 1, '<=', 70], [1, 1, '<=', 100]], // cement transport: (0,0) (50,0) (50,50) (30,70) (0,70)
};
/** Cement transport (in ₹100): P→A 4, P→B 6, P→C 5, Q→A 7, Q→B 5, Q→C 6 per tonne; P 100 t, Q 140 t; A 50, B 70, C 120 t. */
export const tcost = (x, y) => 4 * x + 6 * y + 5 * (100 - x - y) + 7 * (50 - x) + 5 * (70 - y) + 6 * (20 + x + y);
export const S = (reg, p, q, kind) => solveLP(Array.isArray(reg) ? reg : REG[reg], p, q, kind);
export const has = (pts, x, y) => pts.some(([u, v]) => Math.abs(u - x) < 1e-9 && Math.abs(v - y) < 1e-9);
/** Two descriptions of a constraint agree at many lattice and half-lattice points. */
const same = (f, g) => { for (let x = 0; x <= 30; x += 0.5) for (let y = 0; y <= 30; y += 0.5) if (f(x, y) !== g(x, y)) return false; return true; };

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`An imagined orange-juice unit in Nagpur plans how many litres of two juices to bottle each day. In its linear programming model, the decision variables stand for`, opts: ['the quantities the manager is free to choose, here the litres of each juice', 'the fixed limits on machine time and fruit supply', 'the profit earned on each litre', 'the corner points of the feasible region'], key: 'a', sol: 'Decision variables are the unknown quantities to be decided. The limits are the constraints, the profit per litre gives the coefficients of the objective function, and corner points come only after the region is drawn.', d: 1, c: 'recall', t: [1], time: 40 }), (C) => C.key('a'));
Q('m02', mk.mcq({ stem: 'A manager is told that a linear programming model "assumes proportionality". Which of these is therefore a genuine limitation of the method?', opts: ['Profit and resource use are assumed to change in exact proportion to the quantities, which real costs may not do', 'It cannot be used when there are exactly two decision variables', 'It always gives an answer in fractions', 'It ignores the constraints when the region is bounded'], key: 'a', sol: 'Linear programming treats every relation as linear: doubling output doubles profit and resource use. Real situations with discounts or overtime break this. Two-variable problems are exactly the ones solved graphically, answers need not be fractional, and constraints are never ignored.', d: 2, c: 'understanding', t: [1], time: 50 }), (C) => C.key('a'));
Q('m03', mk.mcq({ stem: 'Which of the following is a typical application area of linear programming?', opts: ['Choosing the cheapest mix of foods that still meets nutrient needs', 'Finding the rate at which a balloon\'s volume grows', 'Solving a quadratic equation for a break-even price', 'Drawing a histogram of exam marks'], key: 'a', sol: 'The diet problem is a classic linear programming application. The other three are calculus, algebra and statistics tasks with no linear objective to optimise under constraints.', d: 1, c: 'recall', t: [1], time: 40 }), (C) => C.key('a'));
Q('m04', mk.mcq({ stem: 'A school canteen in an imagined Imphal school wants the cheapest combination of two snacks that gives each child at least a fixed amount of protein and iron. This linear programming problem is of which type?', opts: ['A diet problem', 'A transportation problem', 'A manufacturing problem', 'A problem with no constraints'], key: 'a', sol: 'Minimising the cost of foods subject to minimum nutrient requirements is a diet problem. A transportation problem moves goods from sources to destinations; a manufacturing problem decides how much of each product to make with limited resources.', d: 1, c: 'understanding', t: [1], time: 40 }), (C) => C.key('a'));
Q('m05', mk.mcq({ stem: r`A tailor in Agra has $24$ m of cloth for the day. Each kurta uses $2$ m and each shirt $1.5$ m. If she stitches $x$ kurtas and $y$ shirts, the cloth constraint is`, opts: [r`$4x + 3y \le 48$`, r`$2x + 1.5y \ge 24$`, r`$3x + 4y \le 48$`, r`$2x + 1.5y \le 2.4$`], key: 'a', sol: r`Cloth used: $2x + 1.5y \le 24$; doubling both sides gives $4x + 3y \le 48$. Option (b) reverses the inequality and option (d) uses the wrong unit.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { C.assert(same((x, y) => 2 * x + 1.5 * y <= 24, (x, y) => 4 * x + 3 * y <= 48), 'cloth constraint equivalent'); C.key('a'); });
Q('m06', mk.mcq({ stem: r`A poultry farmer near Namakkal mixes $x$ kg of feed X and $y$ kg of feed Y. Each kilogram of X gives $3$ units of calcium and each kilogram of Y gives $1$ unit; the flock needs at least $12$ units a day. The calcium constraint is`, opts: [r`$3x + y \ge 12$`, r`$3x + y \le 12$`, r`$x + 3y \ge 12$`, r`$3x + y \ge 4$`], key: 'a', sol: r`Calcium supplied is $3x + 1 \cdot y$ and it must be **at least** $12$: $3x + y \ge 12$. Option (c) swaps the coefficients.`, d: 1, c: 'application', t: [2], time: 50 }), (C) => { C.assert(feasible([[3, 1, '>=', 12]], 4, 0) && !feasible([[3, 1, '>=', 12]], 3, 2), '4 kg of X is just enough, 3 kg X + 2 kg Y is not'); C.key('a'); });
Q('m07', mk.mcq({ stem: r`A stall's plan must satisfy $x + y \le 9$, $x + 3y \le 15$, $x \ge 0$, $y \ge 0$. Which of these plans is feasible?`, opts: ['$(6, 3)$', '$(7, 3)$', '$(2, 5)$', '$(9, 1)$'], key: 'a', sol: r`$(6, 3)$: $9 \le 9$ and $15 \le 15$, so it is feasible (a corner). $(7, 3)$ and $(9, 1)$ give $x + y = 10$; $(2, 5)$ gives $x + 3y = 17$.`, d: 1, c: 'understanding', t: [3], time: 60 }), (C) => C.which([[6, 3], [7, 3], [2, 5], [9, 1]].map(([x, y]) => feasible(REG.A1, x, y)), true));
Q('m08', mk.mcq({ stem: r`The four-sided region cut out by $x + y \le 9$, $x + 3y \le 15$ and the axes has four vertices. Which listed point is **not** one of them?`, opts: ['$(0, 9)$', '$(9, 0)$', '$(6, 3)$', '$(0, 5)$'], key: 'a', sol: r`$(0, 9)$ is on $x + y = 9$ but gives $x + 3y = 27 > 15$, so it is not even feasible. The vertices are $(0, 0)$, $(9, 0)$, $(6, 3)$ and $(0, 5)$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { const cs = corners(REG.A1); C.which([[0, 9], [9, 0], [6, 3], [0, 5]].map(([x, y]) => !has(cs, x, y)), true); });
Q('m09', mk.mcq({ stem: r`On the region with vertices $(0, 0)$, $(9, 0)$, $(6, 3)$, $(0, 5)$, a kiosk's earnings $Z = 4x + 5y$ (in ₹ hundred) are to be as large as possible. The greatest value is`, opts: ['$39$', '$36$', '$25$', '$45$'], key: 'a', sol: r`Corner values: $0$, $36$, $24 + 15 = 39$, $25$. The greatest is $39$ at $(6, 3)$. Option (d) uses $(0, 9)$, which is not feasible.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { const s = S('A1', 4, 5, 'max'); C.assert(sameSet(s.corners, [[0, 0], [9, 0], [6, 3], [0, 5]]), 'corners'); C.which([39, 36, 25, 45], s.value); });
Q('m10', mk.mcq({ stem: r`The "at least" conditions $x + y \ge 8$ and $x + 3y \ge 12$, with $x, y \ge 0$, describe a region in the first quadrant. That region is`, opts: ['unbounded', 'a bounded quadrilateral', 'empty', 'a single point'], key: 'a', sol: r`Every point far enough from the origin, for example $(50, 50)$, satisfies both, so the region extends without limit: it is unbounded, with corners $(0, 8)$, $(6, 2)$ and $(12, 0)$.`, d: 2, c: 'understanding', t: [3], time: 50 }), (C) => { const s = S('U1', 1, 1, 'min'); C.which(['unbounded', 'bounded', 'empty', 'point'], s.empty ? 'empty' : s.bounded ? 'bounded' : 'unbounded'); });
Q('m11', mk.mcq({ stem: r`A fertiliser blend must satisfy $x + y \ge 8$ and $x + 3y \ge 12$ ($x, y \ge 0$), giving corners $(0, 8)$, $(6, 2)$, $(12, 0)$ of an unbounded region. The least cost $Z = 3x + 5y$ is`, opts: ['$28$', '$36$', '$40$', 'not attained, because the region is unbounded'], key: 'a', sol: r`Corner values: $40$, $28$, $36$. The smallest is $28$. The open half-plane $3x + 5y < 28$ has no point in common with the region, so the minimum $28$ is attained at $(6, 2)$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { const s = S('U1', 3, 5, 'min'); C.assert(s.exists && !s.bounded, 'min attained on an unbounded region'); C.which([28, 36, 40, 'none'], s.value); });
Q('m12', mk.mcq({ stem: r`On the same unbounded region ($x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$), a student is asked for the **maximum** of $Z = x + 2y$. The correct conclusion is that the maximum`, opts: ['does not exist', 'is $16$, at $(0, 8)$', 'is $12$, at $(12, 0)$', 'is $10$, at $(6, 2)$'], key: 'a', sol: r`The corner values are $16$, $10$, $12$, but the region is unbounded and the point $(0, 20)$ gives $Z = 40 > 16$. The half-plane $x + 2y > 16$ meets the region, so no maximum exists.`, d: 3, c: 'analysis', t: [4], time: 90 }), (C) => { const s = S('U1', 1, 2, 'max'); C.assert(!s.exists && feasible(REG.U1, 0, 20), 'no maximum'); C.which(['none', 16, 12, 10], s.exists ? s.value : 'none'); });
Q('m13', mk.mcq({ stem: r`A courier van can carry at most $4$ crates ($x + y \le 4$), but the contract asks for a load worth at least $18$ units, $3x + 2y \ge 18$ ($x, y \ge 0$). What can be said about these constraints?`, opts: ['No load satisfies them: the feasible region is empty', 'The feasible region is unbounded', 'The only feasible load is $(4, 0)$', 'The feasible region is a triangle'], key: 'a', sol: r`With $x + y \le 4$, the largest value of $3x + 2y$ is $12$ (at $(4, 0)$), short of $18$. No point satisfies both constraints, so the problem is infeasible; even $(4, 0)$ gives only $12$.`, d: 3, c: 'analysis', t: [3], time: 75 }), (C) => { C.assert(S('E1', 1, 1, 'max').empty && S([[1, 1, '<=', 4]], 3, 2, 'max').value === 12, 'empty region'); C.key('a'); });
Q('m14', mk.mcq({ stem: r`A handloom unit's plan is limited by $x + y \le 12$, $2x + y \le 20$ and $x + 3y \le 30$ ($x, y \ge 0$). How many vertices does its feasible region have?`, opts: ['$5$', '$4$', '$6$', '$3$'], key: 'a', sol: r`The vertices are $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$ and $(0, 10)$: a pentagon. With three non-trivial constraints the region can have up to five corners.`, d: 2, c: 'application', t: [3], time: 90 }), (C) => C.which([5, 4, 6, 3], corners(REG.A3).length));
Q('m15', mk.mcq({ stem: r`For the pentagon with vertices $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$, the largest value of $Z = 2x + 5y$ is`, opts: ['$51$', '$50$', '$36$', '$52$'], key: 'a', sol: r`Corner values: $0$, $20$, $36$, $6 + 45 = 51$, $50$. The largest is $51$ at $(3, 9)$, just above $50$ at $(0, 10)$.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => C.which([51, 50, 36, 52], S('A3', 2, 5, 'max').value));
Q('m16', mk.mcq({ stem: r`On that pentagon (vertices $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$), the total number of items $Z = x + y$ is maximised. How many optimal plans are there?`, opts: ['infinitely many', 'exactly one', 'exactly two', 'none'], key: 'a', sol: r`$Z(8, 4) = Z(3, 9) = 12$, larger than at the other corners, so every point of the edge joining them (the line $x + y = 12$) is optimal: infinitely many plans.`, d: 3, c: 'analysis', t: [4], time: 75 }), (C) => { const s = S('A3', 1, 1, 'max'); C.assert(s.value === 12 && sameSet(s.at, [[8, 4], [3, 9]]), 'two optimal corners'); C.key('a'); });
Q('m17', mk.mcq({ stem: r`In a dairy's model, the pasteuriser line $2x + y = 14$ and the packing line $x + 2y = 13$ meet at a vertex of the feasible region. That vertex is`, opts: ['$(5, 4)$', '$(4, 5)$', '$(7, 0)$', '$(6, 2)$'], key: 'a', sol: r`Double the second equation and subtract the first: $3y = 12$, $y = 4$; then $x = 13 - 8 = 5$. Check: $10 + 4 = 14$.`, d: 1, c: 'understanding', t: [3], time: 50 }), (C) => { const y = (2 * 13 - 14) / 3, x = 13 - 2 * y; C.which([[5, 4], [4, 5], [7, 0], [6, 2]], [x, y]); });
Q('m18', mk.mcq({ stem: r`An imagined Anand dairy makes $x$ batches of paneer and $y$ batches of curd subject to $2x + y \le 14$ and $x + 2y \le 13$. The profit is ₹$30$ per paneer batch and ₹$40$ per curd batch (in hundreds). Its greatest profit, in ₹ hundred, is`, opts: ['$310$', '$260$', '$210$', '$330$'], key: 'a', sol: r`Vertices $(0, 0)$, $(7, 0)$, $(5, 4)$, $(0, 6.5)$ give $0$, $210$, $150 + 160 = 310$, $260$. The greatest is $310$ at $(5, 4)$.`, d: 2, c: 'application', t: [4], time: 90 }), (C) => C.which([310, 260, 210, 330], S('A2', 30, 40, 'max').value));
Q('m19', mk.mcq({ stem: r`A hostel mess requires $3x + 4y \ge 24$ units of energy from two dishes. Testing the origin for this constraint, the student should`, opts: [r`note that $0 \ge 24$ is false and shade the side of the line away from the origin`, r`note that $0 \ge 24$ is false and shade the side containing the origin`, 'pick another test point, since the origin lies on the line', r`note that the test is true and shade the side containing the origin`], key: 'a', sol: r`At $(0, 0)$, $3x + 4y = 0$, which is not at least $24$. The origin is outside, so the feasible side of $3x + 4y = 24$ is the side away from it.`, d: 1, c: 'understanding', t: [3], time: 45 }), (C) => { C.assert(!feasible([[3, 4, '>=', 24]], 0, 0) && feasible([[3, 4, '>=', 24]], 8, 0), 'origin outside'); C.key('a'); });
Q('m20', mk.mcq({ stem: r`A mixed set of constraints, $x + 2y \ge 6$, $x + y \le 8$, $x \le 6$ ($x, y \ge 0$), gives a bounded region with vertices $(6, 0)$, $(6, 2)$, $(0, 8)$, $(0, 3)$. The maximum of $Z = 3x + 2y$ on it is`, opts: ['$22$', '$18$', '$16$', '$24$'], key: 'a', sol: r`Corner values: $18$, $18 + 4 = 22$, $16$, $6$. The maximum is $22$ at $(6, 2)$.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { const s = S('M1', 3, 2, 'max'); C.assert(sameSet(s.corners, [[6, 0], [6, 2], [0, 8], [0, 3]]), 'corners'); C.which([22, 18, 16, 24], s.value); });
Q('m21', mk.mcq({ stem: r`A nutrition plan must meet $2x + y \ge 10$, $x + y \ge 7$ and $x + 2y \ge 10$ ($x, y \ge 0$); its vertices are $(0, 10)$, $(3, 4)$, $(4, 3)$, $(10, 0)$. The least value of $Z = 2x + 3y$ is`, opts: ['$17$', '$18$', '$20$', '$30$'], key: 'a', sol: r`Corner values: $30$, $18$, $17$, $20$. The smallest is $17$; the half-plane $2x + 3y < 17$ contains no feasible point, so the minimum is $17$ at $(4, 3)$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { const s = S('U2', 2, 3, 'min'); C.assert(s.exists, 'attained'); C.which([17, 18, 20, 30], s.value); });
Q('m22', mk.mcq({ stem: 'The fundamental result behind the corner point method says that when the feasible region is bounded and non-empty, a linear objective function', opts: ['has both a maximum and a minimum, and each occurs at a corner point', 'has a maximum but possibly no minimum', 'reaches its optimum only at an interior point', 'may have neither a maximum nor a minimum'], key: 'a', sol: 'On a bounded, non-empty feasible region a linear $Z = ax + by$ attains both its maximum and its minimum, and each occurs at a corner point (possibly at two adjacent corners and the edge between them).', d: 1, c: 'recall', t: [4], time: 40 }), (C) => { const a = S('A3', 3, 1, 'max'), b = S('A3', 3, 1, 'min'); C.assert(a.exists && b.exists && a.bounded, 'bounded region has both'); C.key('a'); });
Q('m23', mk.mcq({ stem: r`Depot P near Satna holds $100$ t of cement and sends $x$ t to site A and $y$ t to site B; the rest goes to site C. The amount sent from P to C is`, opts: [r`$100 - x - y$`, r`$x + y - 100$`, r`$100 + x + y$`, r`$50 - x$`], key: 'a', sol: r`Everything P holds is sent out, so $x + y + (\text{P to C}) = 100$, giving $100 - x - y$; it must be non-negative, which is the constraint $x + y \le 100$.`, d: 2, c: 'application', t: [2], time: 60 }), (C) => { C.assert([[20, 30], [50, 50], [0, 0]].every(([x, y]) => x + y + (100 - x - y) === 100), 'balance'); C.key('a'); });
Q('m24', mk.mcq({ stem: 'Which one of the following sets of conditions (each with $x \\ge 0$, $y \\ge 0$) gives a **bounded** feasible region?', opts: [r`$x + y \le 5$`, r`$x + y \ge 5$`, r`$x - y \le 2$`, r`$y \ge 1$`], key: 'a', sol: r`$x + y \le 5$ keeps every point inside the triangle with vertices $(0, 0)$, $(5, 0)$, $(0, 5)$. Each of the others contains points such as $(100, 100)$ or $(0, 100)$, so those regions are unbounded.`, d: 2, c: 'analysis', t: [3], time: 60 }), (C) => C.which([[[1, 1, '<=', 5]], [[1, 1, '>=', 5]], [[1, -1, '<=', 2]], [[0, 1, '>=', 1]]].map((c) => S(c, 1, 1, 'max').bounded && feasible(c, 0, 1) !== null), true));

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`For the dairy constraints $2x + y \le 14$, $x + 2y \le 13$, $x, y \ge 0$, the maximum of $Z = 3x + 2y$ is $23$, attained at $(5, 4)$.`, r: 'On a bounded feasible region, the maximum of a linear objective function occurs at a corner point.', key: 'a', sol: r`Corner values $0$, $21$, $23$, $13$ give the maximum $23$ at $(5, 4)$. R is the corner point result that justifies checking only the corners, so it explains A.`, d: 2, c: 'understanding', t: [4] }), (C) => { const s = S('A2', 3, 2, 'max'); C.assert(s.value === 23 && sameSet(s.at, [[5, 4]]), 'max 23 at (5, 4)'); C.key('a'); });
Q('ar2', mk.ar({ a: r`The region $x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$ is unbounded.`, r: r`A region described only by "$\ge$" constraints with positive coefficients is always bounded.`, key: 'c', sol: r`A is true: $(40, 40)$ is feasible and the region goes on without end. R is false; such constraints keep points **away** from the origin, which makes the region unbounded, as here.`, d: 2, c: 'analysis', t: [3] }), (C) => { C.assert(!S('U1', 1, 1, 'min').bounded && feasible(REG.U1, 40, 40), 'A true'); C.key('c'); });
Q('ar3', mk.ar({ a: r`The origin satisfies the minimum-load condition $3x + 2y \ge 18$.`, r: 'A point is feasible only when it satisfies every constraint of the problem.', key: 'd', sol: r`At $(0, 0)$, $3x + 2y = 0 < 18$, so A is false. R is the correct definition of a feasible point.`, d: 1, c: 'understanding', t: [1] }), (C) => { C.assert(!feasible([[3, 2, '>=', 18]], 0, 0), 'origin infeasible'); C.key('d'); });
Q('ar4', mk.ar({ a: r`On the region $x + 2y \ge 6$, $x + y \le 8$, $x \le 6$, $x, y \ge 0$, the minimum of $Z = 3x + 2y$ is attained at $(0, 3)$.`, r: r`The point $(0, 3)$ lies on the line $x + 2y = 6$.`, key: 'b', sol: r`Corner values: $(6, 0) \to 18$, $(6, 2) \to 22$, $(0, 8) \to 16$, $(0, 3) \to 6$; the minimum $6$ is at $(0, 3)$, so A is true. R is true as well ($0 + 6 = 6$), but $(6, 0)$ also lies on that line and is not optimal, so R does not explain A.`, d: 3, c: 'analysis', t: [4] }), (C) => { const s = S('M1', 3, 2, 'min'); C.assert(s.value === 6 && sameSet(s.at, [[0, 3]]) && 0 + 2 * 3 === 6, 'A and R true'); C.key('b'); });
Q('ar5', mk.ar({ a: r`For the canteen constraints $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$, $x, y \ge 0$, the least value $28$ of $Z = 4x + 4y$ is attained at infinitely many points.`, r: 'If a linear objective takes the same optimal value at two adjacent corners, it takes that value at every point of the edge joining them.', key: 'a', sol: r`$Z(3, 4) = Z(4, 3) = 28$, while $Z(0, 10) = Z(10, 0) = 40$, and $4x + 4y < 28$ (that is, $x + y < 7$) breaks a constraint. So the minimum $28$ holds on the whole edge from $(3, 4)$ to $(4, 3)$: R explains A.`, d: 3, c: 'analysis', t: [4] }), (C) => { const s = S('U2', 4, 4, 'min'); C.assert(s.exists && s.value === 28 && sameSet(s.at, [[3, 4], [4, 3]]), 'edge optimal'); C.key('a'); });
Q('ar6', mk.ar({ a: r`A canteen's linear programming model may include the condition $x \le 30$ for the number of plates of one dish.`, r: 'In a linear programming problem every constraint must be written as an equation.', key: 'c', sol: r`A is true: $x \le 30$ is a linear inequality, a perfectly good constraint. R is false: constraints are usually inequalities; only their boundary lines are equations.`, d: 1, c: 'understanding', t: [1] }), (C) => C.key('c'));

// =============================================================== true-false
Q('tf1', mk.tf({ stem: 'In the graphical method, the decision variables of a linear programming problem may take only whole-number values.', key: 'f', sol: 'False. Linear programming assumes divisibility: the variables may take any non-negative real values, and the optimum may be a fraction such as $(0, 6.5)$. Whole-number answers need extra conditions (or sensible rounding).', d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(has(corners(REG.A2), 0, 6.5), 'a fractional corner exists'); C.key('f'); });
Q('tf2', mk.tf({ stem: r`For the nutrition constraints $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$ ($x, y \ge 0$), the plan $(4, 3)$ is feasible.`, key: 't', sol: r`True: $8 + 3 = 11 \ge 10$, $4 + 3 = 7 \ge 7$ and $4 + 6 = 10 \ge 10$; it is in fact a corner of the region.`, d: 1, c: 'understanding', t: [3] }), (C) => { C.assert(feasible(REG.U2, 4, 3), 'feasible'); C.key('t'); });
Q('tf3', mk.tf({ stem: 'If the feasible region of a linear programming problem is unbounded, the objective function can never have a minimum on it.', key: 'f', sol: r`False. On the unbounded region $x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$, the cost $Z = 3x + 5y$ has the minimum $28$ at $(6, 2)$; the half-plane test confirms it.`, d: 2, c: 'understanding', t: [4] }), (C) => { const s = S('U1', 3, 5, 'min'); C.assert(!s.bounded && s.exists && s.value === 28, 'minimum on an unbounded region'); C.key('f'); });
Q('tf4', mk.tf({ stem: r`On the quadrilateral with vertices $(0, 0)$, $(9, 0)$, $(6, 3)$, $(0, 5)$, the function $Z = 2x + 7y$ is greatest at $(6, 3)$.`, key: 'f', sol: r`False. $Z(6, 3) = 33$, but $Z(0, 5) = 35$ is the greatest of the corner values $0$, $18$, $33$, $35$.`, d: 2, c: 'understanding', t: [4] }), (C) => { const s = S('A1', 2, 7, 'max'); C.assert(s.value === 35 && !has(s.at, 6, 3), 'max at (0, 5)'); C.key('f'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: 'The conditions $x \\ge 0$ and $y \\ge 0$, which say that the quantities produced or bought cannot be negative, are called the ____ constraints.', acc: [['non-negativity', 'non-negative', 'nonnegativity']], sol: 'They are the non-negativity constraints.', d: 1, c: 'recall', t: [1] }), (C) => C.blank('non-negativity'));
Q('fb2', mk.fill({ stem: r`In the handloom model, the boundary lines $x + y = 12$ and $x + 3y = 30$ meet at a vertex whose $y$-coordinate is ____.`, acc: [['9']], sol: r`Subtracting, $2y = 18$, so $y = 9$ (and $x = 3$).`, d: 1, c: 'understanding', t: [3] }), (C) => C.blank((30 - 12) / 2));
Q('fb3', mk.fill({ stem: r`On the quadrilateral with vertices $(0, 0)$, $(9, 0)$, $(6, 3)$, $(0, 5)$, the maximum value of $Z = x + 3y$ is ____.`, acc: [['15']], sol: r`Corner values $0$, $9$, $15$, $15$: the maximum is $15$, reached at two corners and along the edge between them.`, d: 2, c: 'understanding', t: [4] }), (C) => { const s = S('A1', 1, 3, 'max'); C.assert(s.at.length === 2, 'two optimal corners'); C.blank(s.value); });
Q('fb4', mk.fill({ stem: 'A feasible solution at which the objective function takes its best value (largest for a maximum, smallest for a minimum) is called an ____ solution.', acc: [['optimal', 'optimum']], sol: 'It is an optimal (optimum) feasible solution.', d: 1, c: 'recall', t: [4] }), (C) => C.blank('optimal'));

// =============================================================== numerical
Q('n1', mk.num({ stem: r`On the bounded region $x + 2y \ge 6$, $x + y \le 8$, $x \le 6$, $x, y \ge 0$, a cost $Z = x + 4y$ is to be kept as low as possible. Enter its minimum value.`, value: 6, sol: r`Corners $(6, 0)$, $(6, 2)$, $(0, 8)$, $(0, 3)$ give $6$, $14$, $32$, $12$. Minimum $6$ at $(6, 0)$.`, scheme: [['6', 1]], d: 2, c: 'understanding', t: [4], time: 120 }), (C) => C.val(S('M1', 1, 4, 'min').value));
Q('n2', mk.num({ stem: r`An imagined Kanchipuram handloom unit weaves $x$ sarees and $y$ stoles a week with loom hours $x + y \le 12$, dyeing slots $2x + y \le 20$ and finishing hours $x + 3y \le 30$. Profit is ₹$500$ per saree and ₹$300$ per stole. What is the greatest weekly profit in rupees?`, value: 5200, unit: '₹', sol: r`Corners $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$ give ₹$0$, ₹$5000$, ₹$5200$, ₹$4200$, ₹$3000$. Greatest: ₹$5200$ with $8$ sarees and $4$ stoles.`, scheme: [['5200', 1]], d: 3, c: 'application', t: [4], time: 180 }), (C) => C.val(S('A3', 500, 300, 'max').value));
Q('n3', mk.num({ stem: r`In the cement plan with $x \le 50$, $y \le 70$, $x + y \le 100$ ($x, y \ge 0$), the cost (in ₹ hundred) is $C = 1320 - 2x + 2y$. Enter the least possible cost in ₹ hundred.`, value: 1220, sol: r`Corners $(0, 0)$, $(50, 0)$, $(50, 50)$, $(30, 70)$, $(0, 70)$ give $1320$, $1220$, $1320$, $1400$, $1460$. Least: $1220$ at $(50, 0)$.`, scheme: [['1220', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { C.assert([[0, 0], [12, 34], [50, 50]].every(([x, y]) => tcost(x, y) === 1320 - 2 * x + 2 * y), 'cost function'); C.val(1320 + S('T', -2, 2, 'min').value); });
Q('n4', mk.num({ stem: r`The three "at least" nutrient conditions $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$, with $x, y \ge 0$, cut out an open-ended region. How many vertices does it have?`, value: 4, sol: r`They are $(0, 10)$, $(3, 4)$, $(4, 3)$ and $(10, 0)$: $4$ vertices.`, scheme: [['4', 1]], d: 2, c: 'understanding', t: [3], time: 120 }), (C) => C.val(corners(REG.U2).length));
Q('n5', mk.num({ stem: r`The Imphal canteen buys $x$ packets of a millet snack (₹$5$ each) and $y$ packets of a pulse snack (₹$4$ each) subject to $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$. What is the least cost in rupees?`, value: 31, unit: '₹', sol: r`Corners $(0, 10)$, $(3, 4)$, $(4, 3)$, $(10, 0)$ give ₹$40$, ₹$31$, ₹$32$, ₹$50$. The half-plane $5x + 4y < 31$ has no feasible point, so the least cost is ₹$31$.`, scheme: [['31', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { const s = S('U2', 5, 4, 'min'); C.assert(s.exists, 'attained'); C.val(s.value); });

// =============================================================== short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: 'Using an imagined bakery that makes two kinds of biscuits, explain what is meant by (i) the objective function and (ii) the feasible region of a linear programming problem.', model: r`(i) The **objective function** is the linear expression to be maximised or minimised, for example the bakery's profit $Z = 20x + 15y$ for $x$ trays of one biscuit and $y$ of the other.\n\n(ii) The **feasible region** is the set of all points $(x, y)$ that satisfy every constraint (oven time, flour, $x, y \ge 0$) at the same time; only these plans can be carried out.`, sol: 'One definition each, with the context.', scheme: [['Objective function with example', 1], ['Feasible region with example', 1]], d: 1, c: 'understanding', t: [1], time: 120 }), (C) => C.model(['objective function', 'feasible region']));
Q('s202', mk.short({ marks: 2, stem: 'A cooperative in an imagined Kutch village asks whether linear programming is worth learning. State two advantages of the method for planning its production.', model: '1. It gives the **best** (optimal) use of limited resources such as labour, machines and money, instead of a guess.\n\n2. It makes the decision **systematic and clear**: all limits are written down, the effect of changing one of them can be studied, and bottlenecks become visible.', sol: 'Any two genuine advantages.', scheme: [['First advantage', 1], ['Second advantage', 1]], d: 1, c: 'understanding', t: [1], time: 90 }), (C) => C.model(['optimal']));
Q('s203', mk.short({ marks: 2, stem: r`A jeweller in an imagined Jaipur workshop makes $x$ rings and $y$ bangles a day. A ring takes $3$ hours and a bangle $2$ hours, and at most $24$ hours are available; at least $2$ rings must be made. Profit is ₹$400$ per ring and ₹$300$ per bangle. Formulate the linear programming problem.`, model: r`Maximise $Z = 400x + 300y$\n\nSubject to $3x + 2y \le 24$ (hours), $x \ge 2$ (rings), and $y \ge 0$.`, sol: 'Objective, the hours constraint, the minimum-rings constraint and non-negativity.', scheme: [['Objective function', 1], ['Constraints', 1]], d: 2, c: 'application', t: [2], time: 120 }), (C) => { C.assert(same((x, y) => 3 * x + 2 * y <= 24 && x >= 2, (x, y) => feasible([[3, 2, '<=', 24], [1, 0, '>=', 2]], x, y)), 'formulation matches the story'); C.model([400, 300, 24, 2]); });
Q('s204', mk.short({ marks: 2, stem: r`For the dairy constraints $2x + y \le 14$, $x + 2y \le 13$, $x, y \ge 0$, decide whether the plans $P(3, 2)$ and $Q(6, 3)$ are feasible, giving reasons.`, model: r`$P(3, 2)$: $6 + 2 = 8 \le 14$ and $3 + 4 = 7 \le 13$, so $P$ is **feasible**.\n\n$Q(6, 3)$: $12 + 3 = 15 > 14$, so the first constraint fails and $Q$ is **not feasible**.`, sol: 'Substitute each plan into both constraints.', scheme: [['P checked: feasible', 1], ['Q fails the first constraint', 1]], d: 1, c: 'understanding', t: [3], time: 90 }), (C) => { C.assert(feasible(REG.A2, 3, 2) && !feasible(REG.A2, 6, 3), 'P in, Q out'); C.model([8, 7, 15]); });
Q('s205', mk.short({ marks: 2, stem: r`Two boundaries of the canteen's nutrient region are $x + y = 7$ and $x + 2y = 10$. Find the vertex where they meet and check that it satisfies the third condition $2x + y \ge 10$.`, model: r`Subtract: $y = 3$, so $x = 4$. The vertex is $(4, 3)$.\n\nCheck: $2 \cdot 4 + 3 = 11 \ge 10$, so it is a corner of the region.`, sol: 'Eliminate x by subtraction, then test the third condition.', scheme: [['(4, 3)', 1], ['Third condition checked', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { C.assert(has(corners(REG.U2), 4, 3), 'corner'); C.model([4, 3, 11]); });
Q('s206', mk.short({ marks: 2, stem: r`A region has vertices $(6, 0)$, $(6, 2)$, $(0, 8)$ and $(0, 3)$. Find the greatest and least values of $Z = 3x + 2y$ on it.`, model: r`$Z(6, 0) = 18$, $Z(6, 2) = 22$, $Z(0, 8) = 16$, $Z(0, 3) = 6$.\n\nGreatest $22$ at $(6, 2)$; least $6$ at $(0, 3)$.`, sol: 'Evaluate Z at all four corners.', scheme: [['Corner values', 1], ['Greatest and least with points', 1]], d: 2, c: 'application', t: [4], time: 100 }), (C) => { const mx = S('M1', 3, 2, 'max'), mn = S('M1', 3, 2, 'min'); C.assert(mx.value === 22 && mn.value === 6, 'values'); C.model([18, 22, 16, 6]); });
Q('s207', mk.short({ marks: 2, stem: r`On the unbounded region $x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$ (vertices $(0, 8)$, $(6, 2)$, $(12, 0)$), show that the minimum of $Z = x + y$ is attained at infinitely many points.`, model: r`$Z(0, 8) = 8$, $Z(6, 2) = 8$, $Z(12, 0) = 12$. The half-plane $x + y < 8$ breaks the first constraint, so no feasible point does better: the minimum is $8$.\n\nIt occurs at the adjacent corners $(0, 8)$ and $(6, 2)$, hence at every point of the edge joining them: infinitely many points.`, sol: 'Equal values at two adjacent corners plus the half-plane check.', scheme: [['Corner values and half-plane check', 1], ['Edge argument', 1]], d: 3, c: 'analysis', t: [4], time: 120 }), (C) => { const s = S('U1', 1, 1, 'min'); C.assert(s.exists && s.value === 8 && s.at.length === 2, 'two optimal corners'); C.model([8, 12]); });
Q('s208', mk.short({ marks: 2, stem: r`A courier van's constraints are $x + y \le 4$ and $3x + 2y \ge 18$ with $x, y \ge 0$. Show that the problem has no feasible solution.`, model: r`On $x + y \le 4$ (first quadrant) the corners are $(0, 0)$, $(4, 0)$, $(0, 4)$, where $3x + 2y$ is $0$, $12$, $8$; so $3x + 2y \le 12$ everywhere on that triangle.\n\nSince $12 < 18$, no point meets both conditions: the feasible region is empty.`, sol: 'Largest value of 3x + 2y on the first triangle is 12.', scheme: [['Largest value 12 on the triangle', 1], ['Conclusion: empty region', 1]], d: 3, c: 'analysis', t: [3], time: 120 }), (C) => { C.assert(S('E1', 1, 1, 'max').empty && S([[1, 1, '<=', 4]], 3, 2, 'max').value === 12, 'empty'); C.model([12, 18]); });
Q('s209', mk.short({ marks: 2, stem: r`For the unbounded region $x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$, show that $Z = x - y$ has no minimum value.`, model: r`Corner values: $Z(0, 8) = -8$, $Z(6, 2) = 4$, $Z(12, 0) = 12$; the smallest is $-8$.\n\nBut $(0, 9)$ is feasible ($9 \ge 8$, $27 \ge 12$) and gives $Z = -9 < -8$; moving up the $y$-axis makes $Z$ as small as we like, so no minimum exists.`, sol: 'A feasible point beats the best corner, so the half-plane x − y < −8 meets the region.', scheme: [['Corner values', 1], ['Counter-point and conclusion', 1]], d: 3, c: 'analysis', t: [4], time: 120 }), (C) => { const s = S('U1', 1, -1, 'min'); C.assert(!s.exists && feasible(REG.U1, 0, 9) && 0 - 9 < s.value, 'no minimum'); C.model([-8, 4, 12, -9]); });

// =============================================================== short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`A kiosk's plan obeys $x + y \le 9$, $x + 3y \le 15$, $x, y \ge 0$. Using the graphical method, find the maximum of its takings $Z = 4x + 5y$ (in ₹ hundred) and the plan that gives it.`, model: r`Boundary lines: $x + y = 9$ through $(9, 0)$, $(0, 9)$; $x + 3y = 15$ through $(15, 0)$, $(0, 5)$. They meet where $2y = 6$: $(6, 3)$.\n\nThe feasible region is the quadrilateral with corners $(0, 0)$, $(9, 0)$, $(6, 3)$, $(0, 5)$.\n\n$Z$: $0$, $36$, $39$, $25$. Maximum $39$ at $(6, 3)$.`, sol: 'Corners from the intersection, then Z at each corner.', scheme: [['Region and its corners', 1], ['Z at the corners', 1], ['Maximum 39 at (6, 3)', 1]], d: 2, c: 'application', t: [3, 4], time: 210 }), (C) => { const s = S('A1', 4, 5, 'max'); C.assert(s.value === 39 && sameSet(s.at, [[6, 3]]), 'max 39'); C.model([36, 39, 25]); });
Q('s302', mk.short({ marks: 3, stem: r`For the handloom constraints $x + y \le 12$, $2x + y \le 20$, $x + 3y \le 30$, $x, y \ge 0$, find the corners of the feasible region and the maximum of $Z = 5x + 3y$.`, model: r`Intersections: $x + y = 12$ with $2x + y = 20$ gives $(8, 4)$; $x + y = 12$ with $x + 3y = 30$ gives $(3, 9)$. On the axes: $(10, 0)$ and $(0, 10)$.\n\nCorners $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$; $Z = 0, 50, 52, 42, 30$.\n\nMaximum $52$ at $(8, 4)$.`, sol: 'Five corners, then evaluate Z.', scheme: [['Intersection points', 1], ['All corners and Z values', 1], ['Maximum 52 at (8, 4)', 1]], d: 3, c: 'application', t: [4], time: 240 }), (C) => { const s = S('A3', 5, 3, 'max'); C.assert(sameSet(s.corners, [[0, 0], [10, 0], [8, 4], [3, 9], [0, 10]]) && s.value === 52, 'max 52'); C.model([50, 52, 42, 30]); });
Q('s303', mk.short({ marks: 3, stem: r`Minimise $Z = 5x + 4y$ subject to $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$, $x, y \ge 0$, explaining why the answer is a true minimum although the region is unbounded.`, model: r`Corners: $(0, 10)$, $(3, 4)$, $(4, 3)$, $(10, 0)$ with $Z = 40, 31, 32, 50$. The smallest corner value is $31$ at $(3, 4)$.\n\nBecause the region is unbounded, draw the open half-plane $5x + 4y < 31$: it lies entirely below the line through $(3, 4)$ and has no point in common with the region.\n\nHence the minimum is $31$ at $(3, 4)$.`, sol: 'Corner values plus the half-plane test.', scheme: [['Corners', 1], ['Corner values', 1], ['Half-plane check and minimum 31', 1]], d: 3, c: 'application', t: [4], time: 240 }), (C) => { const s = S('U2', 5, 4, 'min'); C.assert(s.exists && s.value === 31 && sameSet(s.at, [[3, 4]]), 'min 31'); C.model([40, 31, 32, 50]); });
Q('s304', mk.short({ marks: 3, stem: r`The Imphal canteen mixes $x$ packets of a millet snack and $y$ packets of a pulse snack. A millet packet gives $2$ units of protein, $1$ unit of iron and $1$ unit of fibre; a pulse packet gives $1$ unit of protein, $1$ unit of iron and $2$ units of fibre. Each class needs at least $10$ units of protein, $7$ of iron and $10$ of fibre. Packets cost ₹$5$ and ₹$4$. Formulate the linear programming problem.`, model: r`Minimise $Z = 5x + 4y$\n\nSubject to $2x + y \ge 10$ (protein), $x + y \ge 7$ (iron), $x + 2y \ge 10$ (fibre), $x \ge 0$, $y \ge 0$.`, sol: 'One constraint per nutrient, an objective for cost.', scheme: [['Objective function', 1], ['Nutrient constraints', 1], ['Non-negativity', 1]], d: 2, c: 'application', t: [2], time: 180 }), (C) => { C.assert(same((x, y) => 2 * x + y >= 10 && x + y >= 7 && x + 2 * y >= 10, (x, y) => feasible(REG.U2, x, y)), 'formulation'); C.model([5, 4, 10, 7]); });
Q('s305', mk.short({ marks: 3, stem: r`On the handloom pentagon with vertices $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$, the total number of pieces $Z = x + y$ is to be as large as possible. Find the maximum and describe all the optimal plans.`, model: r`$Z = 0, 10, 12, 12, 10$ at the corners. The maximum is $12$, at both $(8, 4)$ and $(3, 9)$.\n\nThese corners are adjacent, so $Z = 12$ at every point of the edge joining them, the part of $x + y = 12$ with $3 \le x \le 8$; for example $(5.5, 6.5)$.\n\nThere are infinitely many optimal plans.`, sol: 'Equal maximum at two adjacent corners.', scheme: [['Corner values', 1], ['Maximum 12 at two corners', 1], ['Whole edge optimal', 1]], d: 3, c: 'analysis', t: [4], time: 210 }), (C) => { const s = S('A3', 1, 1, 'max'); C.assert(s.value === 12 && s.at.length === 2 && feasible(REG.A3, 5.5, 6.5), 'edge'); C.model([12, 5.5, 6.5]); });
Q('s306', mk.short({ marks: 3, stem: r`For the bounded region $x + 2y \ge 6$, $x + y \le 8$, $x \le 6$, $x, y \ge 0$, find both the maximum and the minimum of $Z = x + 4y$.`, model: r`Corners: $(6, 0)$, $(6, 2)$ (where $x = 6$ meets $x + y = 8$), $(0, 8)$ and $(0, 3)$.\n\n$Z = 6, 14, 32, 12$.\n\nMaximum $32$ at $(0, 8)$; minimum $6$ at $(6, 0)$.`, sol: 'Four corners, evaluate Z.', scheme: [['Corners', 1], ['Z values', 1], ['Maximum and minimum', 1]], d: 2, c: 'application', t: [4], time: 180 }), (C) => { C.assert(S('M1', 1, 4, 'max').value === 32 && S('M1', 1, 4, 'min').value === 6, 'values'); C.model([6, 14, 32, 12]); });
Q('s307', mk.short({ marks: 3, stem: r`Describe the feasible region of the handloom constraints $x + y \le 12$, $2x + y \le 20$, $x + 3y \le 30$, $x, y \ge 0$: say which constraint bounds it on each stretch, and list its vertices.`, model: r`Along the $x$-axis it runs from $(0, 0)$ to $(10, 0)$, where $2x + y = 20$ cuts the axis.\n\nFrom $(10, 0)$ to $(8, 4)$ the boundary is $2x + y = 20$; from $(8, 4)$ to $(3, 9)$ it is $x + y = 12$; from $(3, 9)$ to $(0, 10)$ it is $x + 3y = 30$; then down the $y$-axis.\n\nVertices: $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$.`, sol: 'Each constraint is the boundary on one stretch.', scheme: [['Axis intercepts', 1], ['Intersections (8, 4) and (3, 9)', 1], ['Boundary order and vertices', 1]], d: 3, c: 'application', t: [3], time: 210 }), (C) => { C.assert(sameSet(corners(REG.A3), [[0, 0], [10, 0], [8, 4], [3, 9], [0, 10]]), 'vertices'); C.model([10, 8, 4, 3, 9]); });
Q('s308', mk.short({ marks: 3, stem: r`On the unbounded region $x + y \ge 8$, $x + 3y \ge 12$, $x, y \ge 0$, find the minimum of $Z = 2x + y$, and decide whether $Z$ has a maximum there.`, model: r`Corners $(0, 8)$, $(6, 2)$, $(12, 0)$ give $Z = 8, 14, 24$. The half-plane $2x + y < 8$ contains no feasible point, so the minimum is $8$ at $(0, 8)$.\n\nFor a maximum: $(30, 0)$ is feasible and gives $60 > 24$; $Z$ grows without limit along the $x$-axis, so there is **no maximum**.`, sol: 'Half-plane test for the minimum; a far feasible point rules out a maximum.', scheme: [['Corner values', 1], ['Minimum 8 with half-plane check', 1], ['No maximum, with reason', 1]], d: 3, c: 'analysis', t: [4], time: 210 }), (C) => { const mn = S('U1', 2, 1, 'min'), mx = S('U1', 2, 1, 'max'); C.assert(mn.exists && mn.value === 8 && !mx.exists && feasible(REG.U1, 30, 0), 'min 8, no max'); C.model([8, 14, 24, 60]); });
Q('s309', mk.short({ marks: 3, stem: 'State three limitations of linear programming that a planner at an imagined Hosur factory should keep in mind.', model: '1. **Linearity:** it assumes profit and resource use change in proportion to output, ignoring discounts, overtime rates and similar effects.\n\n2. **Certainty:** all coefficients (prices, hours, availability) must be known exactly in advance.\n\n3. **Single objective:** it optimises one quantity at a time, though real decisions may involve several goals; and fractional answers may need rounding when items are whole units.', sol: 'Any three genuine limitations.', scheme: [['First limitation', 1], ['Second limitation', 1], ['Third limitation', 1]], d: 1, c: 'recall', t: [1], time: 150 }), (C) => C.model(['Linearity', 'Certainty']));
Q('s310', mk.short({ marks: 3, stem: r`Depots P (holding $100$ t) and Q (holding $140$ t) near Satna supply sites A, B, C needing $50$ t, $70$ t and $120$ t. Let P send $x$ t to A and $y$ t to B. Express the other four shipments in $x$ and $y$, and write the constraints that make every shipment non-negative.`, model: r`P to C: $100 - x - y$. Q to A: $50 - x$. Q to B: $70 - y$. Q to C: $120 - (100 - x - y) = 20 + x + y$.\n\nNon-negative shipments: $x \ge 0$, $y \ge 0$, $x \le 50$, $y \le 70$, $x + y \le 100$ (and $20 + x + y \ge 0$ holds automatically).`, sol: 'Use supplies and demands to express each route.', scheme: [['P to C and Q to A, B', 1], ['Q to C', 1], ['Constraints', 1]], d: 3, c: 'application', t: [2], time: 210 }), (C) => { C.assert(50 + 70 + 120 === 100 + 140, 'balanced'); C.assert([[10, 20], [50, 50], [30, 70]].every(([x, y]) => 50 - x + (70 - y) + (20 + x + y) === 140), 'Q total 140'); C.model([50, 70, 100, 20]); });

// =============================================================== long answer, 5 marks
Q('l01', mk.long({ stem: r`An imagined Anand dairy makes paneer and curd in batches. A paneer batch uses $2$ hours of the pasteuriser and $1$ hour of packing; a curd batch uses $1$ hour of the pasteuriser and $2$ hours of packing. Each day there are $14$ pasteuriser hours and $13$ packing hours. Profit is ₹$3000$ per paneer batch and ₹$4000$ per curd batch.\n\n(a) Formulate the problem as a linear programming problem. [2]\n\n(b) Solve it graphically and state the most profitable plan. [3]`, model: r`**(a)** Let $x$, $y$ be the batches of paneer and curd. Maximise $Z = 3000x + 4000y$ subject to $2x + y \le 14$, $x + 2y \le 13$, $x \ge 0$, $y \ge 0$.\n\n**(b)** The lines meet where $3y = 12$: $(5, 4)$. Corners $(0, 0)$, $(7, 0)$, $(5, 4)$, $(0, 6.5)$.\n\n$Z = 0$, $21000$, $31000$, $26000$.\n\nMaximum ₹$31000$ with $5$ paneer and $4$ curd batches.`, sol: 'Formulate, then the corner point method.', scheme: [['(a) objective', 1], ['(a) constraints', 1], ['(b) corners', 1], ['(b) Z at corners', 1], ['(b) optimum 31000 at (5, 4)', 1]], d: 3, c: 'application', t: [2, 4], time: 480 }), (C) => { const s = S('A2', 3000, 4000, 'max'); C.assert(s.value === 31000 && sameSet(s.at, [[5, 4]]), 'max 31000'); C.model([21000, 31000, 26000, 6.5]); });
Q('l02', mk.long({ stem: r`An imagined Kanchipuram handloom unit weaves $x$ sarees and $y$ stoles a week. A saree needs $1$ loom-day, $2$ dyeing slots and $1$ finishing hour; a stole needs $1$ loom-day, $1$ dyeing slot and $3$ finishing hours. At most $12$ loom-days, $20$ dyeing slots and $30$ finishing hours are available. Profit is ₹$500$ per saree and ₹$300$ per stole.\n\n(a) Write the linear programming problem. [1]\n\n(b) Find the corner points of the feasible region. [2]\n\n(c) Find the plan that maximises profit. [2]`, model: r`**(a)** Maximise $Z = 500x + 300y$ subject to $x + y \le 12$, $2x + y \le 20$, $x + 3y \le 30$, $x, y \ge 0$.\n\n**(b)** $x + y = 12$ meets $2x + y = 20$ at $(8, 4)$ and $x + 3y = 30$ at $(3, 9)$. Corners: $(0, 0)$, $(10, 0)$, $(8, 4)$, $(3, 9)$, $(0, 10)$.\n\n**(c)** $Z = 0$, $5000$, $5200$, $4200$, $3000$. Weave $8$ sarees and $4$ stoles for the maximum profit ₹$5200$.`, sol: 'Three constraints give a pentagon.', scheme: [['(a) formulation', 1], ['(b) intersections', 1], ['(b) all corners', 1], ['(c) Z at corners', 1], ['(c) optimum 5200', 1]], d: 3, c: 'application', t: [2, 4], time: 540 }), (C) => { const s = S('A3', 500, 300, 'max'); C.assert(s.value === 5200 && sameSet(s.at, [[8, 4]]), 'max 5200'); C.model([5000, 5200, 4200, 3000]); });
Q('l03', mk.long({ stem: r`The Imphal school canteen must give each class at least $10$ units of protein, $7$ of iron and $10$ of fibre using $x$ packets of a millet snack ($2$ protein, $1$ iron, $1$ fibre, ₹$5$) and $y$ packets of a pulse snack ($1$ protein, $1$ iron, $2$ fibre, ₹$4$).\n\n(a) Formulate the problem and find the corner points of the feasible region. [3]\n\n(b) Find the cheapest mix, justifying that a minimum exists. [2]`, model: r`**(a)** Minimise $Z = 5x + 4y$ subject to $2x + y \ge 10$, $x + y \ge 7$, $x + 2y \ge 10$, $x, y \ge 0$.\n\nIntersections: $(3, 4)$ from the first two, $(4, 3)$ from the last two. On the axes the binding points are $(0, 10)$ and $(10, 0)$. The region is unbounded with corners $(0, 10)$, $(3, 4)$, $(4, 3)$, $(10, 0)$.\n\n**(b)** $Z = 40$, $31$, $32$, $50$. The half-plane $5x + 4y < 31$ has no point of the region, so the minimum is ₹$31$ with $3$ millet and $4$ pulse packets.`, sol: 'Diet problem on an unbounded region.', scheme: [['(a) formulation', 1], ['(a) intersections', 1], ['(a) corners', 1], ['(b) Z values', 1], ['(b) half-plane check and minimum 31', 1]], d: 4, c: 'application', t: [2, 4], time: 540 }), (C) => { const s = S('U2', 5, 4, 'min'); C.assert(!s.bounded && s.exists && s.value === 31, 'min 31'); C.model([40, 31, 32, 50]); });
Q('l04', mk.long({ stem: r`Depots P ($100$ t) and Q ($140$ t) near Satna supply cement to sites A ($50$ t), B ($70$ t) and C ($120$ t). Costs per tonne, in ₹ hundred: P to A $4$, P to B $6$, P to C $5$; Q to A $7$, Q to B $5$, Q to C $6$. Let P send $x$ t to A and $y$ t to B.\n\n(a) Show that the total cost is $C = 1320 - 2x + 2y$ (₹ hundred) and write the constraints. [3]\n\n(b) Find the cheapest schedule and its cost. [2]`, model: r`**(a)** Shipments: P to C $100 - x - y$; Q to A $50 - x$; Q to B $70 - y$; Q to C $20 + x + y$.\n\n$C = 4x + 6y + 5(100 - x - y) + 7(50 - x) + 5(70 - y) + 6(20 + x + y) = 1320 - 2x + 2y$.\n\nConstraints: $x \le 50$, $y \le 70$, $x + y \le 100$, $x, y \ge 0$.\n\n**(b)** Corners $(0, 0)$, $(50, 0)$, $(50, 50)$, $(30, 70)$, $(0, 70)$ give $C = 1320$, $1220$, $1320$, $1400$, $1460$.\n\nCheapest: $x = 50$, $y = 0$ (P: $50$ t to A, $0$ to B, $50$ t to C; Q: $0$ to A, $70$ t to B, $70$ t to C), costing ₹$1{,}22{,}000$.`, sol: 'A transportation-type problem in two variables.', scheme: [['(a) shipments', 1], ['(a) cost simplified', 1], ['(a) constraints', 1], ['(b) corner values', 1], ['(b) schedule and cost', 1]], d: 4, c: 'analysis', t: [2, 4], time: 600 }), (C) => { C.assert([[0, 0], [7, 31], [50, 50]].every(([x, y]) => tcost(x, y) === 1320 - 2 * x + 2 * y), 'cost formula'); const s = S('T', -2, 2, 'min'); C.assert(1320 + s.value === 1220 && sameSet(s.at, [[50, 0]]), 'min 1220 at (50, 0)'); C.model([1320, 1220, 1400, 1460]); });
Q('l05', mk.long({ stem: r`A spice packer must satisfy $x + 2y \ge 6$ (minimum weight), $x + y \le 8$ (packets per hour) and $x \le 6$ (supply of one spice), with $x, y \ge 0$.\n\n(a) Describe the feasible region and find its corner points. [2]\n\n(b) Find the maximum and the minimum of $Z = 3x + 2y$ on it, stating where each occurs. [3]`, model: r`**(a)** The region lies above $x + 2y = 6$, below $x + y = 8$ and to the left of $x = 6$. It is bounded, with corners $(6, 0)$, $(6, 2)$, $(0, 8)$, $(0, 3)$.\n\n**(b)** $Z(6, 0) = 18$, $Z(6, 2) = 22$, $Z(0, 8) = 16$, $Z(0, 3) = 6$.\n\nMaximum $22$ at $(6, 2)$; minimum $6$ at $(0, 3)$.`, sol: 'A bounded region from mixed constraints.', scheme: [['(a) description', 1], ['(a) corners', 1], ['(b) Z at corners', 1], ['(b) maximum', 1], ['(b) minimum', 1]], d: 3, c: 'application', t: [3, 4], time: 480 }), (C) => { const mx = S('M1', 3, 2, 'max'), mn = S('M1', 3, 2, 'min'); C.assert(mx.bounded && mx.value === 22 && mn.value === 6, 'values'); C.model([18, 22, 16, 6]); });
Q('l06', mk.long({ stem: r`A fertiliser blend must meet $x + y \ge 8$ and $x + 3y \ge 12$, $x, y \ge 0$.\n\n(a) Find the minimum cost $Z = 3x + 5y$, explaining carefully why the corner value is a true minimum. [3]\n\n(b) A trader suggests minimising $W = x - y$ instead. Decide whether $W$ has a minimum on this region and justify your answer. [2]`, model: r`**(a)** Corners $(0, 8)$, $(6, 2)$, $(12, 0)$ give $Z = 40$, $28$, $36$. The region is unbounded, so test the open half-plane $3x + 5y < 28$: it lies on the origin side of the line through $(6, 2)$ and contains no feasible point. Hence the minimum cost is $28$ at $(6, 2)$.\n\n**(b)** Corner values of $W$: $-8$, $4$, $12$. But $(0, 9)$ is feasible and gives $W = -9 < -8$; going further up the $y$-axis makes $W$ as small as we like. So $W$ has **no minimum**: an unbounded region need not have an optimum.`, sol: 'Half-plane test in (a); a counter-point in (b).', scheme: [['(a) corner values', 1], ['(a) half-plane test', 1], ['(a) minimum 28', 1], ['(b) corner values of W', 1], ['(b) no minimum, with reason', 1]], d: 4, c: 'evaluation', t: [4], time: 540 }), (C) => { const a = S('U1', 3, 5, 'min'), b = S('U1', 1, -1, 'min'); C.assert(a.exists && a.value === 28 && !b.exists, 'min 28; W has none'); C.model([40, 28, 36, -8, -9]); });
